const fs=require('node:fs');
const args=process.argv.slice(2);
if(!['login','login status'].includes(args.join(' '))){console.error('Inert QA stub refuses this command');process.exit(94);}
fs.appendFileSync(process.env.QA_CLI_LOG,JSON.stringify({kind:'npm-cmd',args})+'\n');
console.log('INERT CMD '+args.join(' '));

using System;
using System.IO;
public class InertCodex {
  public static int Main(string[] args) {
    string command=String.Join(" ",args);
    if(command!="login" && command!="login status"){Console.Error.WriteLine("Inert QA stub refuses this command");return 94;}
    File.AppendAllText(Environment.GetEnvironmentVariable("QA_CLI_LOG"),"{\"kind\":\"native-exe\",\"command\":\""+command+"\"}\n");
    Console.WriteLine("INERT EXE "+command);return 0;
  }
}
